import React, { memo, useEffect, useMemo, useState } from "react";

import api from "../services/api";
import { useAppContext } from "../context/AppContext";

const DEPARTMENTS = [
  "Department A",
  "Department B",
  "Department C",
  "Department D",
  "Department E",
  "Department F",
  "Department G",
  "Department H",
  "Department I",
];

const STUDENT_DURATIONS = [
  { value: 15, label: "15 Minutes" },
  { value: 30, label: "30 Minutes" },
  { value: 45, label: "45 Minutes" },
  { value: 60, label: "1 Hour" },
];

const formatResourceLabel = (resource) =>
  resource.floor
    ? `${resource.name} - ${resource.floor}`
    : resource.name;

/* 15 minute interval time slots */
const generateTimeSlots = () => {
  const slots = [];

  for (let hour = 8; hour <= 20; hour += 1) {
    for (let minute = 0; minute < 60; minute += 15) {
      if (hour === 20 && minute > 0) break;

      const h = String(hour).padStart(2, "0");
      const m = String(minute).padStart(2, "0");

      slots.push(`${h}:${m}`);
    }
  }

  return slots;
};

const TIME_SLOTS = generateTimeSlots();

const calculateEndTime = (startTime, duration) => {
  if (!startTime || !duration) return "";

  const [hours, minutes] = startTime
    .split(":")
    .map(Number);

  const totalMinutes =
    hours * 60 +
    minutes +
    Number(duration);

  if (totalMinutes >= 24 * 60) {
    return "";
  }

  const endHours = Math.floor(
    totalMinutes / 60
  );

  const endMinutes =
    totalMinutes % 60;

  return `${String(endHours).padStart(
    2,
    "0"
  )}:${String(endMinutes).padStart(
    2,
    "0"
  )}`;
};

const BookingForm = ({
  formData = {},
  onChange = () => {},
  onSubmit = () => {},
  onAvailabilityCheck = () => {},
  availabilityMsg,
  successBooking,
  loading,
  currentUser = {},
}) => {
  const {
    blocks,
    fetchInitialData,
  } = useAppContext();

  const [
    resourceRows,
    setResourceRows,
  ] = useState([]);

  const [
    resourceLoading,
    setResourceLoading,
  ] = useState(false);

  const [
    resourceError,
    setResourceError,
  ] = useState("");

  const [
    duration,
    setDuration,
  ] = useState("30");

  const today =
    new Date()
      .toISOString()
      .slice(0, 10);

  const isStudent =
    currentUser.role === "student" ||
    currentUser.role === "client";

  const safeFormData = {
    resourceScope: "block",
    blockId: "",
    resourceId: "",
    name: "",
    department: "",
    bookingDate: "",
    startTime: "",
    endTime: "",
    purpose: "",
    ...formData,
  };

  const blockOptions = useMemo(
    () => blocks || [],
    [blocks]
  );

  useEffect(() => {
    fetchInitialData?.();
  }, [fetchInitialData]);

  const setField = (
    name,
    value
  ) => {
    onChange({
      target: {
        name,
        value,
      },
    });
  };

  /*
    Student ke liye
    start time ya duration change hote hi
    end time automatically calculate hoga
  */
  useEffect(() => {
    if (
      isStudent &&
      safeFormData.startTime
    ) {
      const endTime =
        calculateEndTime(
          safeFormData.startTime,
          duration
        );

      if (
        endTime &&
        endTime !== safeFormData.endTime
      ) {
        setField(
          "endTime",
          endTime
        );
      }
    }
  }, [
    isStudent,
    safeFormData.startTime,
    duration,
  ]);

  const loadResources =
    async () => {
      setResourceError("");
      setResourceRows([]);

      if (
        safeFormData.resourceScope ===
          "block" &&
        !safeFormData.blockId
      ) {
        return;
      }

      setResourceLoading(true);

      try {
        const url =
          safeFormData.resourceScope ===
          "extra"
            ? "/extra-centers"
            : `/blocks/${safeFormData.blockId}/resources`;

        const response =
          await api.get(
            url,
            { cache: false }
          );

        setResourceRows(
          response.data || []
        );
      } catch (error) {
        setResourceError(
          "Could not load resources for this selection."
        );
      } finally {
        setResourceLoading(false);
      }
    };

  useEffect(() => {
    loadResources();
  }, [
    safeFormData.blockId,
    safeFormData.resourceScope,
  ]);

  const handleScopeChange = (
    value
  ) => {
    if (
      isStudent &&
      value === "extra"
    ) {
      return;
    }

    setField(
      "resourceScope",
      value
    );

    setField(
      "blockId",
      ""
    );

    setField(
      "resourceId",
      ""
    );
  };

  const handleBlockChange = (
    event
  ) => {
    setField(
      "blockId",
      event.target.value
    );

    setField(
      "resourceId",
      ""
    );
  };

  const handleStudentDuration =
    (event) => {
      const selectedDuration =
        event.target.value;

      setDuration(
        selectedDuration
      );

      if (
        safeFormData.startTime
      ) {
        const endTime =
          calculateEndTime(
            safeFormData.startTime,
            selectedDuration
          );

        setField(
          "endTime",
          endTime
        );
      }
    };

  return (
    <section className="glass-panel section-panel booking-surface">

      <div className="panel-heading">
        <span className="panel-icon">
          B
        </span>

        <div>
          <h2>
            New Booking
          </h2>

          <p>
            Choose a block, load its resources,
            check availability, then submit for approval.
          </p>
        </div>
      </div>

      <div className="segmented">

        <button
          type="button"
          className={
            safeFormData.resourceScope ===
            "block"
              ? "active"
              : ""
          }
          onClick={() =>
            handleScopeChange(
              "block"
            )
          }
        >
          Block
        </button>

        {!isStudent ? (
          <button
            type="button"
            className={
              safeFormData.resourceScope ===
              "extra"
                ? "active"
                : ""
            }
            onClick={() =>
              handleScopeChange(
                "extra"
              )
            }
          >
            Extra Centers
          </button>
        ) : null}

      </div>

      <form
        className="modern-form grid-form"
        onSubmit={onSubmit}
      >

        {/* NAME */}

        <label>
          <span>
            Your Name
          </span>

          <input
            name="name"
            value={
              safeFormData.name
            }
            onChange={onChange}
            required
            readOnly
          />
        </label>


        {/* DEPARTMENT DROPDOWN */}

        <label>
          <span>
            Department
          </span>

          <select
            name="department"
            value={
              safeFormData.department
            }
            onChange={onChange}
            required
          >
            <option value="">
              Select Department
            </option>

            {DEPARTMENTS.map(
              (department) => (
                <option
                  key={department}
                  value={department}
                >
                  {department}
                </option>
              )
            )}
          </select>
        </label>


        {/* BLOCK */}

        {safeFormData.resourceScope ===
        "block" ? (

          <label>
            <span>
              Block
            </span>

            <select
              value={
                safeFormData.blockId
              }
              onChange={
                handleBlockChange
              }
              required
            >
              <option value="">
                Select Block
              </option>

              {blockOptions.map(
                (block) => (
                  <option
                    key={block.id}
                    value={block.id}
                  >
                    Block {block.name}
                  </option>
                )
              )}
            </select>
          </label>

        ) : (

          <div className="readonly-tile">
            <span>
              Extra Center
            </span>

            <strong>
              Extra Centers
            </strong>
          </div>

        )}


        {/* RESOURCE */}

        <label>
          <span>
            Resource
          </span>

          <select
            name="resourceId"
            value={
              safeFormData.resourceId
            }
            onChange={onChange}
            required
            disabled={
              resourceLoading ||
              (
                safeFormData.resourceScope ===
                  "block" &&
                !safeFormData.blockId
              )
            }
          >

            <option value="">
              {resourceLoading
                ? "Loading resources..."
                : resourceRows.length
                  ? "Select Resource"
                  : "No resources found"}
            </option>

            {resourceRows.map(
              (resource) => (
                <option
                  key={resource.id}
                  value={resource.id}
                >
                  {formatResourceLabel(
                    resource
                  )}
                </option>
              )
            )}

          </select>
        </label>


        {resourceError ? (
          <div className="notice danger full-width">

            {resourceError}

            <button
              type="button"
              className="inline-button"
              onClick={
                loadResources
              }
            >
              Retry
            </button>

          </div>
        ) : null}


        {/* DATE */}

        <label>
          <span>
            Date
          </span>

          <input
            type="date"
            name="bookingDate"
            value={
              safeFormData.bookingDate
            }
            onChange={onChange}
            min={today}
            required
          />
        </label>


        {/* START TIME */}

        <label>
          <span>
            Start Time
          </span>

          <select
            name="startTime"
            value={
              safeFormData.startTime
            }
            onChange={onChange}
            required
          >

            <option value="">
              Select Start Time
            </option>

            {TIME_SLOTS.map(
              (time) => (
                <option
                  key={time}
                  value={time}
                >
                  {time}
                </option>
              )
            )}

          </select>
        </label>


        {/* STUDENT DURATION */}

        {isStudent ? (

          <label>
            <span>
              Booking Duration
            </span>

            <select
              value={duration}
              onChange={
                handleStudentDuration
              }
              required
            >

              {STUDENT_DURATIONS.map(
                (item) => (
                  <option
                    key={item.value}
                    value={item.value}
                  >
                    {item.label}
                  </option>
                )
              )}

            </select>
          </label>

        ) : null}


        {/* TEACHER END TIME */}

        {!isStudent ? (

          <label>
            <span>
              End Time
            </span>

            <select
              name="endTime"
              value={
                safeFormData.endTime
              }
              onChange={onChange}
              required
            >

              <option value="">
                Select End Time
              </option>

              {TIME_SLOTS.map(
                (time) => (
                  <option
                    key={time}
                    value={time}
                    disabled={
                      safeFormData.startTime &&
                      time <=
                        safeFormData.startTime
                    }
                  >
                    {time}
                  </option>
                )
              )}

            </select>
          </label>

        ) : null}


        {/* STUDENT AUTO END TIME */}

        {isStudent ? (

          <label>
            <span>
              End Time
            </span>

            <input
              type="time"
              value={
                safeFormData.endTime
              }
              readOnly
            />
          </label>

        ) : null}


        {/* PURPOSE */}

        <label className="full-width">

          <span>
            Purpose
          </span>

          <textarea
            name="purpose"
            value={
              safeFormData.purpose
            }
            onChange={onChange}
            required
          />

        </label>


        {/* BUTTONS */}

        <div className="form-actions full-width">

          <button
            type="button"
            className="secondary-action"
            onClick={
              onAvailabilityCheck
            }
            disabled={
              loading ||
              resourceLoading
            }
          >
            Check Availability
          </button>


          <button
            type="submit"
            className="primary-action"
            disabled={
              loading ||
              resourceLoading
            }
          >
            {loading
              ? "Submitting..."
              : "Submit Booking Request"}
          </button>

        </div>

      </form>


      {/* AVAILABILITY MODAL */}

      {availabilityMsg ? (

        <div
          className={`modal-backdrop ${
            availabilityMsg.type ===
            "success"
              ? "success-backdrop"
              : "danger-backdrop"
          }`}
          role="presentation"
        >

          <div className="modal-card glass-panel availability-modal">

            <h3>
              {availabilityMsg.type ===
              "success"
                ? "Available"
                : "Unavailable"}
            </h3>

            <p>
              {availabilityMsg.message}
            </p>


            {availabilityMsg.conflict ? (

              <div className="conflict-box">

                <strong>
                  Conflict
                </strong>

                <span>
                  {
                    availabilityMsg
                      .conflict.date
                  }

                  {" "}

                  {String(
                    availabilityMsg
                      .conflict
                      .start_time
                  ).slice(0, 5)}

                  {" - "}

                  {String(
                    availabilityMsg
                      .conflict
                      .end_time
                  ).slice(0, 5)}
                </span>

              </div>

            ) : null}


            <button
              type="button"
              className="primary-action"
              onClick={() =>
                onChange({
                  target: {
                    name:
                      "dismissAvailability",
                    value: "",
                  },
                })
              }
            >
              Close
            </button>

          </div>

        </div>

      ) : null}


      {/* SUCCESS MODAL */}

      {successBooking ? (

        <div
          className="modal-backdrop success-backdrop"
          role="presentation"
        >

          <div className="modal-card glass-panel availability-modal">

            <h3>
              Booking Request Submitted Successfully
            </h3>

            <p>
              {successBooking
                .resource?.name ||
                `Resource #${successBooking.resource_id}`}
            </p>


            <div className="conflict-box success">

              <span>
                {
                  successBooking
                    .booking_date
                }
              </span>

              <span>
                {String(
                  successBooking
                    .start_time
                ).slice(0, 5)}

                {" - "}

                {String(
                  successBooking
                    .end_time
                ).slice(0, 5)}
              </span>

              <strong>
                Status: Pending
              </strong>

            </div>


            <button
              type="button"
              className="primary-action"
              onClick={() =>
                onChange({
                  target: {
                    name:
                      "dismissSuccess",
                    value: "",
                  },
                })
              }
            >
              Done
            </button>

          </div>

        </div>

      ) : null}

    </section>
  );
};

export default memo(BookingForm);
